// sync_fifo.v - parameterizable synchronous FIFO
// Implements interface_spec.md per microarchitecture.md.
// Storage is not reset (datapath); pointers and count are reset synchronously.
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer AW = $clog2(DEPTH);
    localparam integer CW = $clog2(DEPTH + 1);

    // Sized constants, taken by part-select so every operand width matches.
    localparam [31:0]   DEPTH_U  = DEPTH;
    localparam [31:0]   LAST_U   = DEPTH - 1;
    localparam [31:0]   ONE_U    = 32'd1;
    localparam [AW-1:0] LAST     = LAST_U[AW-1:0];
    localparam [AW-1:0] PTR_ONE  = ONE_U[AW-1:0];
    localparam [CW-1:0] FULL_CNT = DEPTH_U[CW-1:0];
    localparam [CW-1:0] CNT_ONE  = ONE_U[CW-1:0];

    reg  [WIDTH-1:0] mem [0:DEPTH-1];
    reg  [AW-1:0]    wr_ptr_q;
    reg  [AW-1:0]    rd_ptr_q;
    reg  [CW-1:0]    count_q;

    wire             wr_acc;
    wire             rd_acc;
    wire [AW-1:0]    wr_ptr_d;
    wire [AW-1:0]    rd_ptr_d;
    reg  [CW-1:0]    count_d;

    // Flags are compares on a register: no input-to-flag path.
    assign full    = (count_q == FULL_CNT);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;

    // The flags gate the requests: write while full / read while empty dropped.
    assign wr_acc  = wr_en & ~full;
    assign rd_acc  = rd_en & ~empty;

    // Wrap by compare with LAST, so a non power-of-two DEPTH works.
    assign wr_ptr_d = (wr_ptr_q == LAST) ? {AW{1'b0}} : (wr_ptr_q + PTR_ONE);
    assign rd_ptr_d = (rd_ptr_q == LAST) ? {AW{1'b0}} : (rd_ptr_q + PTR_ONE);

    // First-word fall-through: combinational read of the oldest slot.
    assign rd_data = mem[rd_ptr_q];

    always @(*) begin
        count_d = count_q;
        case ({wr_acc, rd_acc})
            2'b10:   count_d = count_q + CNT_ONE;
            2'b01:   count_d = count_q - CNT_ONE;
            default: count_d = count_q;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr_q <= {AW{1'b0}};
            rd_ptr_q <= {AW{1'b0}};
            count_q  <= {CW{1'b0}};
        end else begin
            if (wr_acc) wr_ptr_q <= wr_ptr_d;
            if (rd_acc) rd_ptr_q <= rd_ptr_d;
            count_q <= count_d;
        end
    end

    // Storage: written only outside reset, never reset.
    always @(posedge clk) begin
        if (rst_n && wr_acc) mem[wr_ptr_q] <= wr_data;
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (interface_spec.md section 7).
    // ------------------------------------------------------------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    wire [31:0] f_rd        = {{(32-AW){1'b0}}, rd_ptr_q};
    wire [31:0] f_wr        = {{(32-AW){1'b0}}, wr_ptr_q};
    wire [31:0] f_cnt       = {{(32-CW){1'b0}}, count_q};
    wire [31:0] f_sum       = f_rd + f_cnt;
    wire [31:0] f_wr_expect = (f_sum >= DEPTH_U) ? (f_sum - DEPTH_U) : f_sum;

    always @(*) begin
        if (f_past_valid) begin
            assert (count_q <= FULL_CNT);
            assert (wr_ptr_q <= LAST);
            assert (rd_ptr_q <= LAST);
            assert (full == (count_q == FULL_CNT));
            assert (empty == (count_q == {CW{1'b0}}));
            assert (!(full && empty));
            assert (f_wr == f_wr_expect);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n)) begin
            assert (empty);
            assert (!full);
            assert (count_q == {CW{1'b0}});
            assert (wr_ptr_q == {AW{1'b0}});
            assert (rd_ptr_q == {AW{1'b0}});
        end
        if (f_past_valid && $past(rst_n)) begin
            case ({$past(wr_acc), $past(rd_acc)})
                2'b10:   assert (count_q == $past(count_q) + CNT_ONE);
                2'b01:   assert (count_q == $past(count_q) - CNT_ONE);
                default: assert (count_q == $past(count_q));
            endcase
            if (!$past(wr_acc)) assert (wr_ptr_q == $past(wr_ptr_q));
            if (!$past(rd_acc)) assert (rd_ptr_q == $past(rd_ptr_q));
            if ($past(wr_en) && $past(full) && !$past(rd_en)) begin
                assert (count_q == $past(count_q));
                assert (rd_ptr_q == $past(rd_ptr_q));
            end
            if ($past(rd_en) && $past(empty) && !$past(wr_en)) begin
                assert (count_q == $past(count_q));
                assert (wr_ptr_q == $past(wr_ptr_q));
            end
        end
    end

    // One solver-chosen slot: its word is unchanged while in use and is
    // what rd_data shows when it is the oldest entry.
    (* anyconst *) reg [AW-1:0] f_addr;
    reg [WIDTH-1:0] f_data;

    always @(*) assume (f_addr <= LAST);

    always @(posedge clk) begin
        if (rst_n && wr_acc && (wr_ptr_q == f_addr)) f_data <= wr_data;
    end

    wire [31:0] f_a      = {{(32-AW){1'b0}}, f_addr};
    wire [31:0] f_off    = (f_a >= f_rd) ? (f_a - f_rd) : (f_a + DEPTH_U - f_rd);
    wire        f_in_use = (f_off < f_cnt);

    always @(*) begin
        if (f_past_valid && f_in_use) assert (mem[f_addr] == f_data);
        if (f_past_valid && !empty && (rd_ptr_q == f_addr)) assert (rd_data == f_data);
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover (full);
            cover (full && wr_en && rd_en);
            cover (!empty && rd_en && (rd_ptr_q == f_addr));
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
