// sync_fifo_tb.v - self-checking testbench for sync_fifo
// Two FIFOs on the same stimulus: DEPTH 8 x WIDTH 8 (dut_a) and
// DEPTH 5 x WIDTH 12 (dut_b), each checked every cycle against a queue model.
// Inputs are driven and outputs checked at the falling edge; the DUT samples
// at the rising edge.
module sync_fifo_tb;

  reg         clk     = 1'b0;
  reg         rst_n   = 1'b0;
  reg         wr_en   = 1'b0;
  reg         rd_en   = 1'b0;
  reg  [11:0] wr_data = 12'h000;

  wire        full_a;
  wire        empty_a;
  wire [7:0]  rd_data_a;
  wire [3:0]  count_a;
  wire        full_b;
  wire        empty_b;
  wire [11:0] rd_data_b;
  wire [2:0]  count_b;

  sync_fifo #(.DEPTH(8), .WIDTH(8)) dut_a (
    .clk(clk), .rst_n(rst_n),
    .wr_en(wr_en), .wr_data(wr_data[7:0]), .full(full_a),
    .rd_en(rd_en), .rd_data(rd_data_a), .empty(empty_a),
    .count(count_a)
  );

  sync_fifo #(.DEPTH(5), .WIDTH(12)) dut_b (
    .clk(clk), .rst_n(rst_n),
    .wr_en(wr_en), .wr_data(wr_data), .full(full_b),
    .rd_en(rd_en), .rd_data(rd_data_b), .empty(empty_b),
    .count(count_b)
  );

  always #5 clk = ~clk;

  // Reference queues: 16-entry circular buffers wrapping by 4-bit overflow,
  // independent of the DUT's compare-based wrap.
  reg [7:0]  qa [0:15];
  reg [3:0]  ha = 4'd0;
  reg [3:0]  na = 4'd0;
  reg [11:0] qb [0:15];
  reg [3:0]  hb = 4'd0;
  reg [2:0]  nb = 3'd0;

  // Model of DUT pointer positions, for wrap coverage only.
  integer wpa = 0;
  integer rpa = 0;
  integer wpb = 0;
  integer rpb = 0;

  reg was_full_a = 1'b0;
  reg was_full_b = 1'b0;

  integer passed = 0;
  integer failed = 0;

  // Coverage counters
  integer cov_full_a    = 0;
  integer cov_wfull_a   = 0;
  integer cov_drain_a   = 0;
  integer cov_rempty_a  = 0;
  integer cov_both_e_a  = 0;
  integer cov_both_f_a  = 0;
  integer cov_both_m_a  = 0;
  integer cov_wrapw_a   = 0;
  integer cov_wrapr_a   = 0;
  integer cov_rst_a     = 0;
  integer cov_full_b    = 0;
  integer cov_wfull_b   = 0;
  integer cov_drain_b   = 0;
  integer cov_rempty_b  = 0;
  integer cov_both_e_b  = 0;
  integer cov_both_f_b  = 0;
  integer cov_both_m_b  = 0;
  integer cov_wrapw_b   = 0;
  integer cov_wrapr_b   = 0;
  integer cov_rst_b     = 0;

  reg [31:0]    rnd_d;
  reg [31:0]    rnd_s;
  reg           w;
  reg           r;
  reg           rs;
  integer       i;
  integer       phase;
  integer       got;
  reg [8*64-1:0] nonce;

  // ---------------------------------------------------------------
  // Check every output against the model (state after last edge).
  // ---------------------------------------------------------------
  task check_all;
    begin
      // ---- dut_a: DEPTH 8 ----
      if (count_a !== na) begin
        $error("t=%0t dut_a count=%0d expected %0d", $time, count_a, na);
        failed = failed + 1;
      end else passed = passed + 1;
      if (full_a !== (na == 4'd8)) begin
        $error("t=%0t dut_a full=%b expected %b", $time, full_a, (na == 4'd8));
        failed = failed + 1;
      end else passed = passed + 1;
      if (empty_a !== (na == 4'd0)) begin
        $error("t=%0t dut_a empty=%b expected %b", $time, empty_a, (na == 4'd0));
        failed = failed + 1;
      end else passed = passed + 1;
      if (full_a && empty_a) begin
        $error("t=%0t dut_a full and empty both high", $time);
        failed = failed + 1;
      end else passed = passed + 1;
      if (na != 4'd0) begin
        if (rd_data_a !== qa[ha]) begin
          $error("t=%0t dut_a rd_data=%h expected %h", $time, rd_data_a, qa[ha]);
          failed = failed + 1;
        end else passed = passed + 1;
      end
      if (na == 4'd8) begin
        cov_full_a = cov_full_a + 1;
        was_full_a = 1'b1;
      end
      if ((na == 4'd0) && was_full_a) begin
        cov_drain_a = cov_drain_a + 1;
        was_full_a = 1'b0;
      end

      // ---- dut_b: DEPTH 5 ----
      if (count_b !== nb) begin
        $error("t=%0t dut_b count=%0d expected %0d", $time, count_b, nb);
        failed = failed + 1;
      end else passed = passed + 1;
      if (full_b !== (nb == 3'd5)) begin
        $error("t=%0t dut_b full=%b expected %b", $time, full_b, (nb == 3'd5));
        failed = failed + 1;
      end else passed = passed + 1;
      if (empty_b !== (nb == 3'd0)) begin
        $error("t=%0t dut_b empty=%b expected %b", $time, empty_b, (nb == 3'd0));
        failed = failed + 1;
      end else passed = passed + 1;
      if (full_b && empty_b) begin
        $error("t=%0t dut_b full and empty both high", $time);
        failed = failed + 1;
      end else passed = passed + 1;
      if (nb != 3'd0) begin
        if (rd_data_b !== qb[hb]) begin
          $error("t=%0t dut_b rd_data=%h expected %h", $time, rd_data_b, qb[hb]);
          failed = failed + 1;
        end else passed = passed + 1;
      end
      if (nb == 3'd5) begin
        cov_full_b = cov_full_b + 1;
        was_full_b = 1'b1;
      end
      if ((nb == 3'd0) && was_full_b) begin
        cov_drain_b = cov_drain_b + 1;
        was_full_b = 1'b0;
      end
    end
  endtask

  // ---------------------------------------------------------------
  // Advance the models by the inputs now applied (next rising edge).
  // ---------------------------------------------------------------
  task update_models;
    reg       wacc;
    reg       racc;
    reg [3:0] tail;
    begin
      if (!rst_n) begin
        if (na != 4'd0) cov_rst_a = cov_rst_a + 1;
        if (nb != 3'd0) cov_rst_b = cov_rst_b + 1;
        na = 4'd0;
        ha = 4'd0;
        nb = 3'd0;
        hb = 4'd0;
        wpa = 0;
        rpa = 0;
        wpb = 0;
        rpb = 0;
        was_full_a = 1'b0;
        was_full_b = 1'b0;
      end else begin
        // ---- dut_a ----
        wacc = wr_en && (na != 4'd8);
        racc = rd_en && (na != 4'd0);
        if (wr_en && (na == 4'd8)) cov_wfull_a = cov_wfull_a + 1;
        if (rd_en && (na == 4'd0)) cov_rempty_a = cov_rempty_a + 1;
        if (wr_en && rd_en) begin
          if (na == 4'd0)      cov_both_e_a = cov_both_e_a + 1;
          else if (na == 4'd8) cov_both_f_a = cov_both_f_a + 1;
          else                 cov_both_m_a = cov_both_m_a + 1;
        end
        tail = ha + na;
        if (wacc) begin
          qa[tail] = wr_data[7:0];
          if (wpa == 7) begin
            wpa = 0;
            cov_wrapw_a = cov_wrapw_a + 1;
          end else wpa = wpa + 1;
        end
        if (racc) begin
          ha = ha + 4'd1;
          if (rpa == 7) begin
            rpa = 0;
            cov_wrapr_a = cov_wrapr_a + 1;
          end else rpa = rpa + 1;
        end
        if (wacc && !racc)      na = na + 4'd1;
        else if (racc && !wacc) na = na - 4'd1;

        // ---- dut_b ----
        wacc = wr_en && (nb != 3'd5);
        racc = rd_en && (nb != 3'd0);
        if (wr_en && (nb == 3'd5)) cov_wfull_b = cov_wfull_b + 1;
        if (rd_en && (nb == 3'd0)) cov_rempty_b = cov_rempty_b + 1;
        if (wr_en && rd_en) begin
          if (nb == 3'd0)      cov_both_e_b = cov_both_e_b + 1;
          else if (nb == 3'd5) cov_both_f_b = cov_both_f_b + 1;
          else                 cov_both_m_b = cov_both_m_b + 1;
        end
        tail = hb + {1'b0, nb};
        if (wacc) begin
          qb[tail] = wr_data;
          if (wpb == 4) begin
            wpb = 0;
            cov_wrapw_b = cov_wrapw_b + 1;
          end else wpb = wpb + 1;
        end
        if (racc) begin
          hb = hb + 4'd1;
          if (rpb == 4) begin
            rpb = 0;
            cov_wrapr_b = cov_wrapr_b + 1;
          end else rpb = rpb + 1;
        end
        if (wacc && !racc)      nb = nb + 3'd1;
        else if (racc && !wacc) nb = nb - 3'd1;
      end
    end
  endtask

  // One cycle: check the current state, apply new inputs, advance models.
  task tick;
    input i_rst_n;
    input i_wr;
    input i_rd;
    begin
      @(negedge clk);
      check_all;
      rnd_d   = $random;
      rst_n   = i_rst_n;
      wr_en   = i_wr;
      rd_en   = i_rd;
      wr_data = rnd_d[11:0];
      update_models;
    end
  endtask

  // A coverage goal is a check: it fails the run when never reached.
  task goal;
    input integer id;
    input integer hits;
    begin
      if (hits == 0) begin
        $error("coverage goal %0d not reached", id);
        failed = failed + 1;
      end else passed = passed + 1;
    end
  endtask

  initial begin
    nonce = {64{8'h00}};

    // Reset, with requests asserted during reset (must be ignored).
    tick(1'b0, 1'b0, 1'b0);
    tick(1'b0, 1'b1, 1'b1);
    // Read while empty.
    tick(1'b1, 1'b0, 1'b1);
    // Write and read together while empty: only the write is accepted.
    tick(1'b1, 1'b1, 1'b1);
    tick(1'b1, 1'b0, 1'b1);
    // Fill both to full, then keep writing (writes while full are dropped).
    repeat (10) tick(1'b1, 1'b1, 1'b0);
    // Write and read together while full, then in between.
    repeat (3) tick(1'b1, 1'b1, 1'b1);
    // Drain to empty, then reads while empty.
    repeat (12) tick(1'b1, 1'b0, 1'b1);
    // Partly fill, then simultaneous traffic in between.
    repeat (3) tick(1'b1, 1'b1, 1'b0);
    repeat (6) tick(1'b1, 1'b1, 1'b1);
    // Reset during traffic.
    tick(1'b0, 1'b1, 1'b1);
    tick(1'b0, 1'b1, 1'b0);
    tick(1'b1, 1'b0, 1'b0);
    // Traffic resumes after reset; pointers wrap again.
    repeat (7) tick(1'b1, 1'b1, 1'b0);
    repeat (9) tick(1'b1, 1'b0, 1'b1);

    // Biased random traffic with occasional reset.
    for (i = 0; i < 3000; i = i + 1) begin
      rnd_s = $random;
      phase = (i / 250) % 3;
      case (phase)
        0: begin
          w = (rnd_s[1:0] != 2'b00);
          r = (rnd_s[3:2] == 2'b00);
        end
        1: begin
          w = (rnd_s[1:0] == 2'b00);
          r = (rnd_s[3:2] != 2'b00);
        end
        default: begin
          w = rnd_s[0];
          r = rnd_s[1];
        end
      endcase
      rs = (rnd_s[15:8] != 8'h00);
      tick(rs, w, r);
    end

    // Check the state left by the last inputs.
    tick(1'b1, 1'b0, 1'b0);

    // Coverage goals (interface_spec.md section 7).
    goal(1,  cov_full_a);
    goal(2,  cov_wfull_a);
    goal(3,  cov_drain_a);
    goal(4,  cov_rempty_a);
    goal(5,  cov_both_e_a);
    goal(6,  cov_both_f_a);
    goal(7,  cov_both_m_a);
    goal(8,  cov_wrapw_a);
    goal(9,  cov_wrapr_a);
    goal(10, cov_rst_a);
    goal(11, cov_full_b);
    goal(12, cov_wfull_b);
    goal(13, cov_drain_b);
    goal(14, cov_rempty_b);
    goal(15, cov_both_e_b);
    goal(16, cov_both_f_b);
    goal(17, cov_both_m_b);
    goal(18, cov_wrapw_b);
    goal(19, cov_wrapr_b);
    goal(20, cov_rst_b);
